INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_111'), 1, 'List the rules in the OpenAPI schema of the request body (required, minimum, maximum, maxLength, enum). Which of them did any request break on purpose?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_111'), 2, 'An off-by-one bug moves a boundary by one. Which inputs land on different sides of the boundary in a correct and in a buggy implementation?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_111'), 3, 'Read the failing test''s name in the pytest output. What does it tell you before you open the test file?');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_111');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_111'), 'The team''s first suite came from the Postman collection the mobile developers used:

```text
$ pytest tests/api/test_orders.py -q
........................................   [100%]
40 passed in 3.21s
```

```yaml
# openapi.yaml (POST /orders request body)
quantity:
  type: integer
  minimum: 1
  maximum: 20
note:
  type: string
  maxLength: 200
```

Every request in the collection was a real, valid order. The next week production received orders with `quantity: 0` and a 230-character note.

Statement: "All 40 requests pass, so the endpoint enforces its contract; the bad orders must come from another endpoint."', 'single_choice'::question_type, 'False. Forty valid orders exercise one rule: valid input is accepted. None of them sends `quantity: 0`, 21 or a 201-character note, so the suite says nothing about whether `minimum`, `maximum` or `maxLength` are enforced. A suite tests the contract only when each rule has a case that breaks it. The misconception is that many passing tests mean high coverage of behaviour.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_111') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_111'), 'For `quantity` (integer, minimum 1, maximum 20) a reviewer proposes these values:

```python
@pytest.mark.parametrize("quantity, status", [
    (0, 422), (1, 201), (20, 201), (21, 422),
])
```

Statement: "These four values sit on both sides of both boundaries; adding a middle value such as 7 would not catch an off-by-one bug that these miss."', 'single_choice'::question_type, 'True. An off-by-one bug moves a boundary by exactly one, so it changes the outcome only for the values next to the boundary: 0 and 1 at the bottom, 20 and 21 at the top. Any middle value (7) is accepted by the correct and by the buggy code alike. The valid example still belongs in the suite once, as the happy path. The misconception is that more values in the middle add confidence about the edges.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_111') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_111'), 'A failing run of the parametrized suite:

```text
FAILED tests/api/test_orders.py::test_create_order[note-over-max-length] - assert 201 == 422
1 failed, 23 passed in 2.04s
```

Statement: "Because each case is named after the rule it breaks, this output already tells the on-call developer which rule of the contract the API no longer enforces."', 'single_choice'::question_type, 'True. With `pytest.param(..., id="note-over-max-length")` (or `ids=`), the test id carries the rule, so the report reads "note longer than maxLength was accepted (201, not 422)" without opening the code. Auto-generated ids like `test_create_order[body17]` force everyone to count cases. The misconception is that test names matter only for the author.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_111') AND order_index = 3)
    RETURNING id
)
