-- challenge chal_coding_pat_112 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pat_112', (SELECT id FROM catalog.course WHERE public_id = 'python-api-testing'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-api-testing') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pat-1-1' AND is_deleted = false LIMIT 1), 'derive-cases-from-schema', 'Generate test cases from the request schema', 'Rice Rocket''s suite will build its cases from the OpenAPI request schema instead of from a Postman collection. The editor holds `test_cases.py`: `derive_cases(schema)` with its rule blocks missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that each rule of the contract gets the cases described at the top of the file: a missing case per required property, a wrong-type case, both sides of `minimum` / `maximum` and of `minLength` / `maxLength`, every `enum` value and one that is not allowed. Run sends every case to the real validation rules (they must agree with each expectation) and to builds with known bugs (the cases must catch them).', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
