INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_112'), 1, 'For each kind of rule, ask which input sits just inside it and which just outside: those two cases decide whether the rule is enforced.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_112'), 2, 'Look at the table in the docstring: ids, values (`minimum - 1`, `maxLength + 1`, the example as a string) and the order of the cases. Each case changes one property of `base` through `case(...)`.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_112'), 3, 'For a `rating` integer from 1 to 5 the same idea gives `case("rating-at-min", "rating", 1, "accepted")`, `case("rating-below-min", "rating", 0, "rejected")`, `case("rating-at-max", "rating", 5, "accepted")` and `case("rating-above-max", "rating", 6, "rejected")`; for a `comment` of at most 500 characters, `"x" * 500` and `"x" * 501`.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_112'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"missing-required","label":"A case for each required property left out","code":"if name in required:\n    body = {k: v for k, v in base.items() if k != name}\n    cases.append({\"id\": f\"missing-{name}\", \"body\": body, \"expect\": \"rejected\"})"},{"id":"wrong-type","label":"The example sent as the wrong JSON type","code":"wrong = str(spec[\"example\"]) if kind == \"integer\" else 12345\ncase(f\"{name}-wrong-type\", name, wrong, \"rejected\")"},{"id":"integer-bounds","label":"Both sides of an integer''s minimum and maximum","code":"if kind == \"integer\":\n    if \"minimum\" in spec:\n        case(f\"{name}-at-min\", name, spec[\"minimum\"], \"accepted\")\n        case(f\"{name}-below-min\", name, spec[\"minimum\"] - 1, \"rejected\")\n    if \"maximum\" in spec:\n        case(f\"{name}-at-max\", name, spec[\"maximum\"], \"accepted\")\n        case(f\"{name}-above-max\", name, spec[\"maximum\"] + 1, \"rejected\")"},{"id":"string-lengths","label":"Both sides of a string''s length limits","code":"if kind == \"string\":\n    if spec.get(\"minLength\", 0) > 0:\n        case(f\"{name}-at-min-length\", name, \"x\" * spec[\"minLength\"], \"accepted\")\n        case(f\"{name}-under-min-length\", name, \"x\" * (spec[\"minLength\"] - 1), \"rejected\")\n    if \"maxLength\" in spec:\n        case(f\"{name}-at-max-length\", name, \"x\" * spec[\"maxLength\"], \"accepted\")\n        case(f\"{name}-over-max-length\", name, \"x\" * (spec[\"maxLength\"] + 1), \"rejected\")"},{"id":"enum-values","label":"Every allowed value, and one that is not allowed","code":"if \"enum\" in spec:\n    for value in spec[\"enum\"]:\n        case(f\"{name}-is-{value}\", name, value, \"accepted\")\n    case(f\"{name}-not-in-enum\", name, f\"not-a-{name}\", \"rejected\")"},{"id":"integer-bounds-far-values","label":"Both sides of an integer''s minimum and maximum","code":"if kind == \"integer\":\n    if \"minimum\" in spec:\n        case(f\"{name}-at-min\", name, spec[\"minimum\"], \"accepted\")\n        case(f\"{name}-below-min\", name, spec[\"minimum\"] - 100, \"rejected\")\n    if \"maximum\" in spec:\n        case(f\"{name}-at-max\", name, spec[\"maximum\"], \"accepted\")\n        case(f\"{name}-above-max\", name, spec[\"maximum\"] + 100, \"rejected\")","distractor":true},{"id":"missing-required-first-only","label":"A case for each required property left out","code":"if required and name == required[0]:\n    body = {k: v for k, v in base.items() if k != name}\n    cases.append({\"id\": f\"missing-{name}\", \"body\": body, \"expect\": \"rejected\"})","distractor":true},{"id":"string-lengths-far-values","label":"Both sides of a string''s length limits","code":"if kind == \"string\":\n    if spec.get(\"minLength\", 0) > 0:\n        case(f\"{name}-at-min-length\", name, \"x\" * spec[\"minLength\"], \"accepted\")\n        case(f\"{name}-under-min-length\", name, \"\", \"rejected\")\n    if \"maxLength\" in spec:\n        case(f\"{name}-at-max-length\", name, \"x\" * spec[\"maxLength\"], \"accepted\")\n        case(f\"{name}-over-max-length\", name, \"x\" * (spec[\"maxLength\"] * 2), \"rejected\")","distractor":true}]'::jsonb)
