-- challenge chal_coding_pat_122 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pat_122', (SELECT id FROM catalog.course WHERE public_id = 'python-api-testing'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-api-testing') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pat-1-2' AND is_deleted = false LIMIT 1), 'response-schema-validator', 'Check whole responses against their schema', 'The courier app crashed twice on responses the suite called fine: `total` sent as a string, and `courier` null on an unassigned order. The editor holds `schema_check.py`: `validate(schema, value)` with its rule blocks missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that a response is checked against the whole schema (a JSON Schema / OpenAPI 3.1 subset): JSON types (true is a boolean, not an integer; nullable types), required properties (null is present, not missing), nested properties and arrays, properties that are not allowed, enums, minimums and RFC 3339 date-times with an offset. Every problem is reported with its path, in the order the file''s docstring gives. Run checks real and broken order responses.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
