       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_122'), 'The serializer change: total arrives as a string', '{"schema":{"type":"object","required":["id","status","total","items","courier","placed_at"],"properties":{"id":{"type":"integer","minimum":1},"status":{"type":"string","enum":["placed","cooking","on_the_way","delivered","cancelled"]},"total":{"type":"integer","minimum":0},"items":{"type":"array","items":{"type":"object","required":["name","quantity","price"],"properties":{"name":{"type":"string"},"quantity":{"type":"integer","minimum":1},"price":{"type":"integer","minimum":0}}}},"courier":{"type":["object","null"],"required":["id","name"],"additionalProperties":false,"properties":{"id":{"type":"integer"},"name":{"type":"string"}}},"placed_at":{"type":"string","format":"date-time"}}},"responses":{"total_as_string":{"id":91822,"status":"on_the_way","total":"125000","items":[{"name":"Com tam suon","quantity":2,"price":55000},{"name":"Tra da","quantity":1,"price":15000}],"courier":{"id":3107,"name":"Tran Van Binh"},"placed_at":"2026-11-06T11:30:00+07:00"}}}', '{"total_as_string":["$.total: expected integer, got string"]}', 4, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_122'), 'Every problem is reported, with its path: status, an item quantity and a time without offset', '{"schema":{"type":"object","required":["id","status","total","items","courier","placed_at"],"properties":{"id":{"type":"integer","minimum":1},"status":{"type":"string","enum":["placed","cooking","on_the_way","delivered","cancelled"]},"total":{"type":"integer","minimum":0},"items":{"type":"array","items":{"type":"object","required":["name","quantity","price"],"properties":{"name":{"type":"string"},"quantity":{"type":"integer","minimum":1},"price":{"type":"integer","minimum":0}}}},"courier":{"type":["object","null"],"required":["id","name"],"additionalProperties":false,"properties":{"id":{"type":"integer"},"name":{"type":"string"}}},"placed_at":{"type":"string","format":"date-time"}}},"responses":{"several":{"id":91822,"status":"COOKING","total":125000,"items":[{"name":"Com tam suon","quantity":2,"price":55000},{"name":"Tra da","quantity":0,"price":15000}],"courier":{"id":3107,"name":"Tran Van Binh"},"placed_at":"2026-11-06T11:30:00"}}}', '{"several":["$.status: \"COOKING\" is not one of [\"placed\", \"cooking\", \"on_the_way\", \"delivered\", \"cancelled\"]","$.items[1].quantity: 0 is below the minimum 1","$.placed_at: not a date-time with an offset"]}', 4, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_122'), 'A leaked courier phone, a missing field and a boolean price', '{"schema":{"type":"object","required":["id","status","total","items","courier","placed_at"],"properties":{"id":{"type":"integer","minimum":1},"status":{"type":"string","enum":["placed","cooking","on_the_way","delivered","cancelled"]},"total":{"type":"integer","minimum":0},"items":{"type":"array","items":{"type":"object","required":["name","quantity","price"],"properties":{"name":{"type":"string"},"quantity":{"type":"integer","minimum":1},"price":{"type":"integer","minimum":0}}}},"courier":{"type":["object","null"],"required":["id","name"],"additionalProperties":false,"properties":{"id":{"type":"integer"},"name":{"type":"string"}}},"placed_at":{"type":"string","format":"date-time"}}},"responses":{"leaks":{"id":91822,"status":"on_the_way","total":125000,"items":[{"name":"Com tam suon","quantity":2,"price":true}],"courier":{"id":3107,"name":"Tran Van Binh","phone":"0901234567"}}}}', '{"leaks":["$.placed_at: missing","$.items[0].price: expected integer, got boolean","$.courier.phone: not allowed"]}', 4, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_122'), 'Integer, number and nullable object types follow JSON, not Python', '{"schema":{"type":"object","required":["id","status","total","items","courier","placed_at"],"properties":{"id":{"type":"integer","minimum":1},"status":{"type":"string","enum":["placed","cooking","on_the_way","delivered","cancelled"]},"total":{"type":"integer","minimum":0},"items":{"type":"array","items":{"type":"object","required":["name","quantity","price"],"properties":{"name":{"type":"string"},"quantity":{"type":"integer","minimum":1},"price":{"type":"integer","minimum":0}}}},"courier":{"type":["object","null"],"required":["id","name"],"additionalProperties":false,"properties":{"id":{"type":"integer"},"name":{"type":"string"}}},"placed_at":{"type":"string","format":"date-time"}}},"responses":{"float_total":{"id":91822,"status":"on_the_way","total":125000,"items":[{"name":"Com tam suon","quantity":2,"price":55000},{"name":"Tra da","quantity":1,"price":15000}],"courier":{"id":3107,"name":"Tran Van Binh"},"placed_at":"2026-11-06T11:30:00+07:00"},"fraction":{"id":91822,"status":"on_the_way","total":99.5,"items":[{"name":"Com tam suon","quantity":2,"price":55000},{"name":"Tra da","quantity":1,"price":15000}],"courier":{"id":3107,"name":"Tran Van Binh"},"placed_at":"2026-11-06T11:30:00+07:00"},"courier_list":{"id":91822,"status":"on_the_way","total":125000,"items":[{"name":"Com tam suon","quantity":2,"price":55000},{"name":"Tra da","quantity":1,"price":15000}],"courier":[],"placed_at":"2026-11-06T11:30:00+07:00"},"utc":{"id":91822,"status":"on_the_way","total":125000,"items":[{"name":"Com tam suon","quantity":2,"price":55000},{"name":"Tra da","quantity":1,"price":15000}],"courier":{"id":3107,"name":"Tran Van Binh"},"placed_at":"2026-11-06T04:30:00.250Z"}}}', '{"float_total":[],"fraction":["$.total: expected integer, got number"],"courier_list":["$.courier: expected object or null, got array"],"utc":[]}', 4, false, 