INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_131'), 1, 'Ask what a client does with the status code before it reads the body: a mobile app''s HTTP client decides success or failure from the code alone.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_131'), 2, 'Separate the two questions an API answers about a caller: do I know who you are, and are you allowed to do this?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_131'), 3, 'Read the contract text quoted with the evidence: it decides which of two plausible codes is right for this API.');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_131');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_131'), 'A test for ordering from a closed restaurant, and what the API answered:

```python
def test_order_closed_restaurant(api):
    response = api.post("/orders", json={**ORDER, "restaurant_id": 17})
    assert response.status_code < 500
```

```text
HTTP/1.1 200 OK
Content-Type: application/json

{"error": "restaurant closed"}
```

Statement: "The test is right to pass: 200 is not a server error, so the API handled the request correctly."', 'single_choice'::question_type, 'False. The order was not created, but the status says it was: every HTTP client, retry layer and dashboard treats 200 as success, and the courier app showed "order placed". The contract asks for 409 with a problem type for a closed restaurant, and the test should assert that exact code. `< 500` only proves the server did not crash. The misconception is that the body''s text is part of what clients check.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_131') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
