FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_131'), 'A courier (valid token, role `courier`) calls an admin endpoint:

```text
GET /admin/payouts
Authorization: Bearer eyJhbGciOi... (valid, role=courier)

HTTP/1.1 401 Unauthorized
WWW-Authenticate: Bearer
```

Statement: "401 is the right answer, because the courier is not authorized to see payouts."', 'single_choice'::question_type, 'False. Despite its name, 401 means the request is not authenticated (no or invalid credentials), and it tells the client to log in again; the app would sign the courier out. The token is valid and identifies the courier, who simply lacks the permission: that is 403 Forbidden. The misconception comes from the reason phrase "Unauthorized".', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_131') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
