WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_131'), 'Rice Rocket''s contract says: "400 when the body is not valid JSON; 422 when it is valid JSON that breaks a rule of the schema". Two requests:

```text
POST /orders   {"quantity": 2,           -> 400
POST /orders   {"quantity": 0}            -> 422
```

Statement: "Under this contract both answers are right, and a test that accepts any 4xx would miss an API that swaps them."', 'single_choice'::question_type, 'True. The first body cannot be parsed, the second parses but breaks `minimum: 1`, and the contract gives them different codes; clients use the difference (a 400 is a bug in the client, a 422 is a user input to show next to the field). A test asserting `400 <= status < 500` passes when the API swaps them. Some APIs use 400 for both; what matters is that the contract says which and the test asserts it exactly.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_131') AND order_index = 3)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
