        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_pat_132 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pat_132', (SELECT id FROM catalog.course WHERE public_id = 'python-api-testing'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-api-testing') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pat-1-3' AND is_deleted = false LIMIT 1), 'fix-response-assertions', 'Fix the response assertions', 'Every API test of Rice Rocket goes through `check_response(expected, response)`, and the old version let three bugs reach production: a 400 where the contract says 422 ("same class"), a 200 carrying `{"error": ...}`, and error bodies in several shapes. It also failed correct responses whose content type carried `; charset=utf-8` or whose field errors came in another order. The editor holds `assertions.py` with its checks missing, each marked by a `# [ ]` line; some pieces are the old buggy checks. Fill every line so the helper follows the rules in the file''s docstring: the exact status, no error body on a success, RFC 9457 problem details for errors (media type, members, status, type, field pointers in any order) and Retry-After on 429.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
