       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_132'), 'A rule violation answered 400 instead of 422 fails on the status', '{"wrong_4xx":{"expected":{"status":422,"problem_type":"https://api.ricerocket.vn/problems/validation","pointers":["/quantity"]},"response":{"status":400,"headers":{"content-type":"application/problem+json"},"body":{"type":"https://api.ricerocket.vn/problems/validation","title":"Request failed","status":400,"errors":[{"pointer":"/quantity"}]}}}}', '{"wrong_4xx":["status: expected 422, got 400"]}', 4, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_132'), 'A closed restaurant: 200 with an error body fails, whatever the test expected', '{"closed_restaurant":{"expected":{"status":409,"problem_type":"https://api.ricerocket.vn/problems/restaurant-closed","pointers":null},"response":{"status":200,"headers":{"content-type":"application/json"},"body":{"error":"restaurant closed"}}},"menu_with_error":{"expected":{"status":200,"problem_type":null,"pointers":null},"response":{"status":200,"headers":{"content-type":"application/json"},"body":{"error":"menu unavailable"}}}}', '{"closed_restaurant":["status: expected 409, got 200"],"menu_with_error":["body: error body on a success status"]}', 4, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_132'), 'A 404 in the old shape: wrong content type and none of the problem members', '{"unknown_order":{"expected":{"status":404,"problem_type":null,"pointers":null},"response":{"status":404,"headers":{"Content-Type":"application/json"},"body":{"message":"Order not found"}}}}', '{"unknown_order":["content-type: expected application/problem+json, got application/json","body: missing type","body: missing title","body: missing status"]}', 4, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_132'), 'A 429 without Retry-After and with a body that claims 500', '{"rate_limited":{"expected":{"status":429,"problem_type":null,"pointers":null},"response":{"status":429,"headers":{"CONTENT-TYPE":"application/problem+json"},"body":{"type":"https://api.ricerocket.vn/problems/rate-limited","title":"Request failed","status":500}}},"rate_limited_ok":{"expected":{"status":429,"problem_type":null,"pointers":null},"response":{"status":429,"headers":{"Content-Type":"application/problem+json","Retry-After":"30"},"body":{"type":"https://api.ricerocket.vn/problems/rate-limited","title":"Request failed","status":429}}}}', '{"rate_limited":["body.status: expected 429, got 500","retry-after: missing"],"rate_limited_ok":[]}', 4, false, true, 5);
