-- challenge chal_quiz_pat_141 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_pat_141', (SELECT id FROM catalog.course WHERE public_id = 'python-api-testing'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-api-testing') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pat-2-1' AND is_deleted = false LIMIT 1), 'consumer-driven-contracts-quiz', 'Read the contract failures', 'Three statements about consumer-driven contract tests between Rice Rocket''s courier app and its order API. Decide whether each one is true.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
