INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_141'), 1, 'Ask who wrote each test and from what knowledge: the provider''s tests describe what the provider thinks it returns; who knows what the app reads?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_141'), 2, 'Imagine the provider adds a field or returns another order tomorrow. Which pacts break, and should they?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_141'), 3, 'A pact is verified against provider versions. What does a deploy pipeline need to know before it ships one provider version?');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_141');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_141'), 'The order API renamed a field. Its own suite was green; the courier app broke:

```text
# order-api CI
tests/api/test_orders.py ........................ 24 passed

# courier app, production
TypeError: undefined is not a number  at formatEta(order.eta_minutes)
```

```diff
-  "eta_minutes": 12,
+  "eta": 12,
```

Statement: "The provider''s tests passed because they assert what the provider believes its response is; only a contract written from the courier app''s side records that the app reads `eta_minutes`."', 'single_choice'::question_type, 'True. The provider changed the code and its tests together, so they agree with each other and say nothing about clients. A consumer-driven contract (a pact) is written by the consumer from the fields it really uses, published to a broker, and verified against every provider build. Here the verification would report `$.eta_minutes: missing` before the deploy. The misconception is that good provider tests protect clients.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_141') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_141'), 'A developer proposes making the pact stricter:

```json
"response": {
  "status": 200,
  "body": { "id": 91822, "status": "on_the_way", "eta_minutes": 12, "total": 125000,
            "items": [{"name": "Com tam suon", "quantity": 2, "price": 55000}],
            "courier": {"id": 3107, "name": "Tran Van Binh", "phone": "0901234567"},
            "placed_at": "2026-11-06T11:30:00+07:00", "tip": 0, "promo_code": null }
}
```

Statement: "Copying the whole provider response as literal values makes the contract safer, because any change at all is caught."', 'single_choice'::question_type, 'False. A pact should contain only what the consumer reads, with type matchers instead of today''s values. A full literal copy breaks when the provider adds a field the app ignores, returns another order in the provider state, or changes a price; every such failure is noise that teaches people to skip verification. It also hides which fields matter. The misconception is that more assertions always mean more safety.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_141') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_141'), 'The deploy job of the order API runs the Pact Broker''s check before shipping:

```text
$ pact-broker can-i-deploy --pacticipant order-api --version 4f2a9c1 --to-environment production
Computer says no ¯\_(ツ)_/¯

CONSUMER     | C.VERSION | PROVIDER  | P.VERSION | SUCCESS?
courier-app  | 2.14.0    | order-api | 4f2a9c1   | false
```

Statement: "The job should stop: the version of the courier app running in production has a pact that this order API build failed to verify."', 'single_choice'::question_type, 'True. can-i-deploy looks up the verification results between this provider version and the consumer versions recorded as deployed in production; one failed verification means shipping would break a client that users run right now. The fix is to keep `eta_minutes` (or add `eta` alongside it) until the app version that reads `eta` is everywhere. The misconception is that a contract failure is the consumer''s problem to fix later.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_141') AND order_index = 3)
    RETURNING id
)
