-- challenge chal_coding_pat_142 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pat_142', (SELECT id FROM catalog.course WHERE public_id = 'python-api-testing'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-api-testing') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pat-2-1' AND is_deleted = false LIMIT 1), 'verify-consumer-pact', 'Verify the courier app''s pact', 'The courier app now publishes a pact for GET /orders/{id}: the parts of the response it reads, written with matchers. The editor holds `verify_pact.py`: `verify(expected, actual)` with its matching rules missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that `$like` matches by JSON type (recursively for objects), `$regex` fully matches strings, `$eachLike` checks a minimum length and each element''s types, plain objects check only the keys the consumer reads, and plain values match exactly. Run verifies the pact against several builds of the order API: the one that renamed `eta_minutes` must fail, a build that only adds fields or returns other data must pass.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
