INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_142'), 1, 'Think about what a consumer can rely on: the presence and type of the fields it reads. Which of the matchers compare values, and which only types?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_142'), 2, 'Look at how an object compares keys (consumer keys only, or both sides), what `$like` compares, and whether `$eachLike` enforces its `min`.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_142'), 3, 'A pact for a restaurant list could read `{"restaurants": {"$eachLike": {"id": 1, "name": "Pho 24"}, "min": 1}, "page": {"$like": 1}}`: `{"restaurants": [], "page": 1}` fails (`expected at least 1 elements, got 0`), `{"restaurants": [{"id": 9, "name": "Bun Cha", "open": true}], "page": 2, "total": 40}` passes.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_142'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"match-like","label":"Same type as the example, not the same value","code":"if isinstance(expected, dict) and \"$like\" in expected:\n    return like(expected[\"$like\"], actual, path)"},{"id":"match-regex","label":"A string that fully matches the pattern","code":"if isinstance(expected, dict) and \"$regex\" in expected:\n    if not isinstance(actual, str) or not re.fullmatch(expected[\"$regex\"], actual):\n        return [f\"{path}: {json.dumps(actual)} does not match {expected[''$regex'']}\"]\n    return []"},{"id":"match-each-like","label":"Enough elements, each like the example","code":"if isinstance(expected, dict) and \"$eachLike\" in expected:\n    minimum = expected.get(\"min\", 1)\n    if not isinstance(actual, list):\n        return [f\"{path}: expected array, got {json_type(actual)}\"]\n    if len(actual) < minimum:\n        return [f\"{path}: expected at least {minimum} elements, got {len(actual)}\"]\n    problems = []\n    for i, item in enumerate(actual):\n        problems += like(expected[\"$eachLike\"], item, f\"{path}[{i}]\")\n    return problems"},{"id":"object-members","label":"Only the keys the consumer reads","code":"if isinstance(expected, dict):\n    if not isinstance(actual, dict):\n        return [f\"{path}: expected object, got {json_type(actual)}\"]\n    problems = []\n    for key, sub in expected.items():\n        if key not in actual:\n            problems.append(f\"{path}.{key}: missing\")\n        else:\n            problems += verify(sub, actual[key], f\"{path}.{key}\")\n    return problems"},{"id":"match-literal","label":"Exactly the value in the pact","code":"if json_type(actual) != json_type(expected) or actual != expected:\n    return [f\"{path}: expected {json.dumps(expected)}, got {json.dumps(actual)}\"]"},{"id":"match-each-like-no-min","label":"Enough elements, each like the example","code":"if isinstance(expected, dict) and \"$eachLike\" in expected:\n    if not isinstance(actual, list):\n        return [f\"{path}: expected array, got {json_type(actual)}\"]\n    problems = []\n    for i, item in enumerate(actual):\n        problems += like(expected[\"$eachLike\"], item, f\"{path}[{i}]\")\n    return problems","distractor":true},{"id":"match-like-same-value","label":"Same type as the example, not the same value","code":"if isinstance(expected, dict) and \"$like\" in expected:\n    if actual != expected[\"$like\"]:\n        return [f\"{path}: expected {json.dumps(expected[''$like''])}, got {json.dumps(actual)}\"]\n    return []","distractor":true},{"id":"object-members-strict","label":"Only the keys the consumer reads","code":"if isinstance(expected, dict):\n    if not isinstance(actual, dict):\n        return [f\"{path}: expected object, got {json_type(actual)}\"]\n    problems = []\n    for key, sub in expected.items():\n        if key not in actual:\n            problems.append(f\"{path}.{key}: missing\")\n        else:\n            problems += verify(sub, actual[key], f\"{path}.{key}\")\n    problems += [f\"{path}.{key}: not in the pact\" for key in actual if key not in expected]\n    return problems","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, snippets = EXCLUDED.snippets, updated_at = now();
