-- challenge chal_coding_pat_152 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pat_152', (SELECT id FROM catalog.course WHERE public_id = 'python-api-testing'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-api-testing') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pat-2-2' AND is_deleted = false LIMIT 1), 'test-data-fixtures', 'Fix the test data fixtures', 'Rice Rocket''s API suite became order-dependent: it passed in the usual order and failed under pytest-randomly, a run killed by CI blocked every later run with `409 email already used`, and staging collected thousands of orphaned QA customers. The editor holds `tests/conftest.py` with its fixture blocks missing, each marked by a `# [ ]` line; some pieces are the old, buggy versions. Fill every line so that each test gets its own customer and its own restaurant, emails never collide across tests, runs or leftovers of a killed run, nothing is left on staging (customers can only be deleted once their orders are gone) whether a test passes or fails, and the shared seed restaurant 1 is never touched. The docstring is the exact contract; the runner at the bottom plays a small pytest against a fake staging API.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
