INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_152'), 1, 'For each fixture ask: could another test, another CI run or a run that crashed yesterday have created the same thing, and does anything outside this test depend on it?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_152'), 2, 'Look at what makes the email unique (`run[''run_id'']`, `run[''seq'']()`), whether the restaurant is created or borrowed, and the order of the DELETE calls after `yield`: what does the API answer when a customer still has orders?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_152'), 3, 'A fixture for couriers in another suite: `email = f"courier+{run[''run_id'']}-{run[''seq'']()}@example.test"`, `status, body = api.post("/couriers", {...})`, then `try: yield courier` / `finally:` delete the courier''s deliveries first, the courier last.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_152'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"unique-email","label":"An email no other test, run or retry can hold","code":"email = f\"qa+{run[''run_id'']}-{run[''seq'']()}@ricerocket.test\""},{"id":"customer-teardown","label":"Remove the customer and its orders, even on failure","code":"try:\n    yield created\nfinally:\n    for order in api.get(f\"/orders?customer_id={created[''id'']}\")[1]:\n        api.delete(f\"/orders/{order[''id'']}\")\n    api.delete(f\"/customers/{created[''id'']}\")"},{"id":"own-restaurant","label":"A restaurant only this test uses, removed after it","code":"status, body = api.post(\"/restaurants\", {\"name\": f\"QA Kitchen {run[''run_id'']}-{run[''seq'']()}\", \"open\": True})\nassert status == 201, f\"POST /restaurants -> {status} {body}\"\ncreated = {\"id\": body[\"id\"]}\ntry:\n    yield created\nfinally:\n    for order in api.get(f\"/orders?restaurant_id={created[''id'']}\")[1]:\n        api.delete(f\"/orders/{order[''id'']}\")\n    api.delete(f\"/restaurants/{created[''id'']}\")"},{"id":"customer-deleted-first","label":"Remove the customer and its orders, even on failure","code":"try:\n    yield created\nfinally:\n    api.delete(f\"/customers/{created[''id'']}\")\n    for order in api.get(f\"/orders?customer_id={created[''id'']}\")[1]:\n        api.delete(f\"/orders/{order[''id'']}\")","distractor":true},{"id":"shared-seed-restaurant","label":"A restaurant only this test uses, removed after it","code":"created = {\"id\": 1}\ntry:\n    yield created\nfinally:\n    for order in api.get(f\"/orders?restaurant_id={created[''id'']}\")[1]:\n        api.delete(f\"/orders/{order[''id'']}\")","distractor":true},{"id":"unique-email-fixed","label":"An email no other test, run or retry can hold","code":"email = \"qa@ricerocket.test\"","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, snippets = EXCLUDED.snippets, updated_at = now();
