VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_152'), 'One CI run: every test passes and nothing is left on staging', '{"runs":["ci-4101"],"order":["test_place_order","test_closed_restaurant_rejects_orders","test_email_is_unique","test_reorder"]}', '{"runs":[{"test_place_order":"passed","test_closed_restaurant_rejects_orders":"passed","test_email_is_unique":"passed","test_reorder":"passed"}],"left_behind":{"customers":0,"orders":0,"restaurants":0,"seed_restaurant_open":true}}', 6, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_152'), 'Random order: the closed-restaurant test runs first and the others still pass', '{"runs":["ci-4101"],"order":["test_closed_restaurant_rejects_orders","test_place_order","test_reorder","test_email_is_unique"]}', '{"runs":[{"test_closed_restaurant_rejects_orders":"passed","test_place_order":"passed","test_reorder":"passed","test_email_is_unique":"passed"}],"left_behind":{"customers":0,"orders":0,"restaurants":0,"seed_restaurant_open":true}}', 6, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_152'), 'A test that fails after creating orders still leaves nothing behind', '{"runs":["ci-4101"],"order":["test_place_order","test_closed_restaurant_rejects_orders","test_email_is_unique","test_reorder"],"crash":["test_reorder","test_place_order"]}', '{"runs":[{"test_place_order":"failed: simulated failure after the request","test_closed_restaurant_rejects_orders":"passed","test_email_is_unique":"passed","test_reorder":"failed: simulated failure after the request"}],"left_behind":{"customers":0,"orders":0,"restaurants":0,"seed_restaurant_open":true}}', 6, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_152'), 'A killed CI job left its QA customers behind: the next run is not blocked by them', '{"runs":["ci-4101"],"order":["test_place_order","test_closed_restaurant_rejects_orders","test_email_is_unique","test_reorder"],"leftovers":[{"email":"qa@ricerocket.test"},{"email":"qa+ci-4100-1@ricerocket.test"}]}', '{"runs":[{"test_place_order":"passed","test_closed_restaurant_rejects_orders":"passed","test_email_is_unique":"passed","test_reorder":"passed"}],"left_behind":{"customers":0,"orders":0,"restaurants":0,"seed_restaurant_open":true}}', 6, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_152'), 'Two runs back to back on the same staging API, in two different orders', '{"runs":["ci-4101","ci-4102"],"order":["test_closed_restaurant_rejects_orders","test_reorder","test_place_order","test_email_is_unique"]}', '{"runs":[{"test_closed_restaurant_rejects_orders":"passed","test_reorder":"passed","test_place_order":"passed","test_email_is_unique":"passed"},{"test_closed_restaurant_rejects_orders":"passed","test_reorder":"passed","test_place_order":"passed","test_email_is_unique":"passed"}],"left_behind":{"customers":0,"orders":0,"restaurants":0,"seed_restaurant_open":true}}', 6, false, true, 5);
