-- challenge chal_coding_pat_162 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pat_162', (SELECT id FROM catalog.course WHERE public_id = 'python-api-testing'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-api-testing') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pat-2-3' AND is_deleted = false LIMIT 1), 'idempotency-checks', 'Write the idempotency checks for POST /orders', 'Couriers'' phones retry `POST /orders` after a timeout, and last month some customers were charged twice. The API team says idempotency keys are implemented; the only test sent each request once. The editor holds `tests/test_idempotency.py` with the five checks missing, each marked by a `# [ ]` line; some pieces test the wrong thing on purpose. Fill every line so that the suite proves the contract in the docstring: a replay returns the first answer marked `Idempotent-Replayed: true`, a reused key with another body gets 422, a duplicate during processing gets 409, a retry after a lost response never creates a second order, and a request without a key gets 400. Run plays your checks against a correct API and against APIs with one known defect each: every defect must be caught by the right checks, and the correct API must pass them all.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
