VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_171'), 1, 'A rerun makes a failure disappear from the report. Ask whether it also removes the thing two tests were fighting over.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_171'), 2, 'pytest-xdist starts separate processes. Where does a session-scoped fixture live, and how many sessions are there?'),
