UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_171');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_171'), 'Since the switch to four workers, a few tests fail on most runs, never the same ones:

```text
$ pytest -n 4 -q
FAILED tests/test_courier.py::test_courier_accepts_order - assert 409 == 200 (courier is busy)
FAILED tests/test_receipts.py::test_receipt - read back: ''receipt for order 5112''
2 failed, 61 passed in 52.10s
```

Statement: "These are timing glitches of the staging API; adding pytest-rerunfailures with `--reruns 3` fixes the cause, since the tests pass on the rerun."', 'single_choice'::question_type, 'False. Both failures are tests fighting over the same thing: one demo courier accepting two deliveries, and one fixed receipt file written by two workers. A rerun usually lands at another moment and passes, so the report turns green while the coupling stays; it also hides the next real regression behind a retry. The fix is to give each test its own courier and its own file (`tmp_path`). Reruns are for failures you cannot control, such as a third-party sandbox, and should be counted and reported, not hidden.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pat_171') AND order_index = 1)
    RETURNING id
)
