INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_182'), 1, 'Read the report the way the on-call engineer would: which line tells them it is one bug and not forty, and which value lets them find the request in the server logs?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_182'), 2, 'Look at the path segments that differ between failures (numbers, UUIDs, the query string), at where a token can hide (headers, nested JSON keys, plain-text bodies), and at the outcome of each test''s last attempt.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_182'), 3, 'Grouping log lines of a worker: `key = f"{job_type} {queue_template} -> {exit_code}"`, `groups.setdefault(key, []).append(line)`, then `sorted(groups.items(), key=lambda kv: (-len(kv[1]), kv[0]))`; a token in `{"auth": {"token": ...}}` is found by walking dicts and lists recursively.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_182'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"endpoint-template","label":"Turn ids in the path into one template","code":"path = path.split(\"?\", 1)[0]\nreturn \"/\".join(\"{id}\" if s.isdigit() or UUID.match(s) else s for s in path.split(\"/\"))"},{"id":"redact-secrets","label":"Hide credentials in headers and in the body","code":"clean_headers = {k: \"[REDACTED]\" if k.lower() in SECRET_HEADERS else v for k, v in headers.items()}\n\ndef scrub(value):\n    if isinstance(value, dict):\n        return {k: \"[REDACTED]\" if k in SECRET_KEYS else scrub(v) for k, v in value.items()}\n    if isinstance(value, list):\n        return [scrub(v) for v in value]\n    return value\n\ntry:\n    clean_body = json.dumps(scrub(json.loads(body)), separators=(\",\", \":\"))\nexcept ValueError:\n    clean_body = re.sub(r\"Bearer\\s+\\S+\", \"Bearer [REDACTED]\", body)\nreturn clean_headers, clean_body"},{"id":"failure-record","label":"Request, request id and error of a failure","code":"try:\n    error = json.loads(exchange[\"response_body\"]).get(\"title\") or f\"HTTP {exchange[''status'']}\"\nexcept (ValueError, AttributeError):\n    error = f\"HTTP {exchange[''status'']}\"\nresponse_headers = {k.lower(): v for k, v in exchange[\"response_headers\"].items()}\nreturn {\n    \"test\": test,\n    \"request\": f\"{exchange[''method'']} {exchange[''url''].split(''?'', 1)[0]}\",\n    \"endpoint\": f\"{exchange[''method'']} {endpoint_template(exchange[''url''])}\",\n    \"status\": exchange[\"status\"],\n    \"request_id\": response_headers.get(\"x-request-id\"),\n    \"error\": error,\n    \"excerpt\": body[:120],\n    \"request_headers\": headers,\n}"},{"id":"flaky-tests","label":"Tell flaky tests from failing ones","code":"if attempts[-1][\"outcome\"] == \"passed\":\n    if any(a[\"outcome\"] == \"failed\" for a in attempts):\n        flaky.append(result[\"test\"])\n    continue"},{"id":"group-failures","label":"One group per root cause, biggest first","code":"groups = {}\nfor r in records:\n    groups.setdefault(f\"{r[''endpoint'']} -> {r[''status'']} {r[''error'']}\", []).append(r)\nordered = sorted(groups.items(), key=lambda kv: (-len(kv[1]), kv[0]))\ngroup_list = [{\n    \"signature\": signature,\n    \"count\": len(rs),\n    \"tests\": sorted(r[\"test\"] for r in rs),\n    \"request_ids\": sorted(r[\"request_id\"] for r in rs if r[\"request_id\"]),\n} for signature, rs in ordered]"},{"id":"endpoint-raw-path","label":"Turn ids in the path into one template","code":"return path.split(\"?\", 1)[0]","distractor":true},{"id":"flaky-any-failure","label":"Tell flaky tests from failing ones","code":"if any(a[\"outcome\"] == \"failed\" for a in attempts) and len(attempts) > 1:\n    flaky.append(result[\"test\"])\nif attempts[-1][\"outcome\"] == \"passed\":\n    continue","distractor":true},{"id":"redact-headers-only","label":"Hide credentials in headers and in the body","code":"clean_headers = {k: \"[REDACTED]\" if k.lower() in SECRET_HEADERS else v for k, v in headers.items()}\nreturn clean_headers, body","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, snippets = EXCLUDED.snippets, updated_at = now();
