       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_182'), 'Tokens in headers and in a JSON body never reach the report', '{"results":[{"test":"tests/test_auth.py::test_refresh_rotates_token","attempts":[{"outcome":"failed","exchange":{"method":"POST","url":"/auth/refresh","request_headers":{"Authorization":"Bearer rt-77c1","Cookie":"session=s3cr3t","X-Api-Key":"k-qa-1","Accept":"application/json"},"status":401,"response_headers":{"X-Request-Id":"req-11aa02","Content-Type":"application/problem+json"},"response_body":"{\"title\":\"Refresh token reused\",\"access_token\":\"at-91f2\",\"user\":{\"id\":7,\"otp\":\"482913\"}}"}}]}]}', '{"groups":[{"signature":"POST /auth/refresh -> 401 Refresh token reused","count":1,"tests":["tests/test_auth.py::test_refresh_rotates_token"],"request_ids":["req-11aa02"]}],"flaky":[],"records":[{"test":"tests/test_auth.py::test_refresh_rotates_token","request":"POST /auth/refresh","endpoint":"POST /auth/refresh","status":401,"request_id":"req-11aa02","error":"Refresh token reused","excerpt":"{\"title\":\"Refresh token reused\",\"access_token\":\"[REDACTED]\",\"user\":{\"id\":7,\"otp\":\"[REDACTED]\"}}","request_headers":{"Authorization":"[REDACTED]","Cookie":"[REDACTED]","X-Api-Key":"[REDACTED]","Accept":"application/json"}}]}', 6, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_182'), 'A test that failed and then passed on a rerun is flaky, not a failure', '{"results":[{"test":"tests/test_menu.py::test_menu_cache","attempts":[{"outcome":"failed","exchange":{"method":"GET","url":"/restaurants/42/menu","request_headers":{"Authorization":"Bearer eyJhbGciOiJIUzI1NiJ9.qa-courier.sig","Content-Type":"application/json"},"status":504,"response_headers":{},"response_body":"upstream timed out"}},{"outcome":"passed"}]},{"test":"tests/test_courier.py::test_courier_accepts_order","attempts":[{"outcome":"failed","exchange":{"method":"POST","url":"/orders/5112/accept","request_headers":{"Authorization":"Bearer eyJhbGciOiJIUzI1NiJ9.qa-courier.sig","Content-Type":"application/json"},"status":500,"response_headers":{"X-Request-Id":"req-7f3a01","Content-Type":"application/problem+json"},"response_body":"{\"type\":\"https://api.ricerocket.vn/problems/internal\",\"title\":\"Courier assignment failed\",\"status\":500,\"detail\":\"column courier_zone does not exist\"}"}}]}]}', '{"groups":[{"signature":"POST /orders/{id}/accept -> 500 Courier assignment failed","count":1,"tests":["tests/test_courier.py::test_courier_accepts_order"],"request_ids":["req-7f3a01"]}],"flaky":["tests/test_menu.py::test_menu_cache"],"records":[{"test":"tests/test_courier.py::test_courier_accepts_order","request":"POST /orders/5112/accept","endpoint":"POST /orders/{id}/accept","status":500,"request_id":"req-7f3a01","error":"Courier assignment failed","excerpt":"{\"type\":\"https://api.ricerocket.vn/problems/internal\",\"title\":\"Courier assignment failed\",\"status\":500,\"detail\":\"column ","request_headers":{"Authorization":"[REDACTED]","Content-Type":"application/json"}}]}', 6, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pat_182'), 'Two root causes, UUID paths, a plain-text body with a bearer token, and a passing test', '{"results":[{"test":"tests/test_payments.py::test_refund","attempts":[{"outcome":"failed","exchange":{"method":"POST","url":"/payments/3f2b8c1e-9a4d-4c6b-8e2f-1a2b3c4d5e6f/refund","request_headers":{"Authorization":"Bearer eyJhbGciOiJIUzI1NiJ9.qa-courier.sig","Content-Type":"application/json"},"status":502,"response_headers":{"X-Request-Id":"req-55e010","Content-Type":"application/problem+json"},"response_body":"gateway error: Authorization Bearer sk_live_abc123 rejected"}}]},{"test":"tests/test_payments.py::test_refund_twice","attempts":[{"outcome":"failed","exchange":{"method":"POST","url":"/payments/0b9c8d7e-6f5a-4b3c-9d2e-8f7a6b5c4d3e/refund","request_headers":{"Authorization":"Bearer eyJhbGciOiJIUzI1NiJ9.qa-courier.sig","Content-Type":"application/json"},"status":502,"response_headers":{"X-Request-Id":"req-55e031","Content-Type":"application/problem+json"},"response_body":"gateway error: Authorization Bearer sk_live_def456 rejected"}},{"outcome":"failed","exchange":{"method":"POST","url":"/payments/0b9c8d7e-6f5a-4b3c-9d2e-8f7a6b5c4d3e/refund","request_headers":{"Authorization":"Bearer eyJhbGciOiJIUzI1NiJ9.qa-courier.sig","Content-Type":"application/json"},"status":502,"response_headers":{"X-Request-Id":"req-55e044","Content-Type":"application/problem+json"},"response_body":"gateway error: Authorization Bearer sk_live_def456 rejected"}}]},{"test":"tests/test_courier.py::test_accept_twice_is_409","attempts":[{"outcome":"failed","exchange":{"method":"POST","url":"/orders/5140/accept","request_headers":{"Authorization":"Bearer eyJhbGciOiJIUzI1NiJ9.qa-courier.sig","Content-Type":"application/json"},"status":500,"response_headers":{"X-Request-Id":"req-7f3a19","Content-Type":"application/problem+json"},"response_body":"{\"type\":\"https://api.ricerocket.vn/problems/internal\",\"title\":\"Couri